#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    int top;
    int capacity;
} ArrayStack;

void stack_init(ArrayStack *st, int capacity) {
    st->capacity = capacity;
    st->top = -1;
    st->data = (int *)malloc(capacity * sizeof(int));
}

void stack_push(ArrayStack *st, int val) {
    if (st->top >= st->capacity - 1) {
        printf("OVERFLOW\n");
        return;
    }
    st->data[++st->top] = val;
}

void stack_pop(ArrayStack *st) {
    if (st->top == -1) {
        printf("UNDERFLOW\n");
        return;
    }
    printf("%d\n", st->data[st->top--]);
}

void stack_peek(ArrayStack *st) {
    if (st->top == -1) {
        printf("EMPTY\n");
        return;
    }
    printf("%d\n", st->data[st->top]);
}

void stack_is_empty(ArrayStack *st) {
    printf("%s\n", (st->top == -1) ? "TRUE" : "FALSE");
}

void stack_size(ArrayStack *st) {
    printf("%d\n", st->top + 1);
}

void stack_destroy(ArrayStack *st) {
    if (st->data) {
        free(st->data);
        st->data = NULL;
    }
    st->top = -1;
    st->capacity = 0;
}

int main() {
    int cap, q;
    if (scanf("%d %d", &cap, &q) != 2) return 0;

    ArrayStack st;
    stack_init(&st, cap);

    char cmd[16];
    for (int i = 0; i < q; i++) {
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "PUSH") == 0) {
            int val; scanf("%d", &val);
            stack_push(&st, val);
        } else if (strcmp(cmd, "POP") == 0) {
            stack_pop(&st);
        } else if (strcmp(cmd, "PEEK") == 0) {
            stack_peek(&st);
        } else if (strcmp(cmd, "ISEMPTY") == 0) {
            stack_is_empty(&st);
        } else if (strcmp(cmd, "SIZE") == 0) {
            stack_size(&st);
        }
    }

    stack_destroy(&st);
    return 0;
}

