#include <stdio.h>
#include <string.h>
#include <ctype.h>

int precedence(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}

int is_right_associative(char op) {
    return (op == '^');
}

void infix_to_postfix(const char *infix, char *postfix) {
    char stack[512];
    int top = -1;
    int k = 0;

    for (int i = 0; infix[i] != '\0'; i++) {
        char ch = infix[i];

        if (isalnum(ch)) {
            postfix[k++] = ch;
        } else if (ch == '(') {
            stack[++top] = ch;
        } else if (ch == ')') {
            while (top != -1 && stack[top] != '(') {
                postfix[k++] = stack[top--];
            }
            if (top != -1 && stack[top] == '(') {
                top--; // Discard '('
            }
        } else {
            // Operator
            int prec = precedence(ch);
            int right_assoc = is_right_associative(ch);
            while (top != -1 && stack[top] != '(') {
                int top_prec = precedence(stack[top]);
                if (top_prec > prec || (top_prec == prec && !right_assoc)) {
                    postfix[k++] = stack[top--];
                } else {
                    break;
                }
            }
            stack[++top] = ch;
        }
    }

    while (top != -1) {
        if (stack[top] != '(') {
            postfix[k++] = stack[top];
        }
        top--;
    }
    postfix[k] = '\0';
}

