long long evaluate_postfix(char *expr) {
    long long stack[1024];
    int top = -1;

    char *token = strtok(expr, " ");
    while (token != NULL) {
        if (strcmp(token, "+") == 0) {
            long long b = stack[top--];
            long long a = stack[top--];
            stack[++top] = a + b;
        } else if (strcmp(token, "-") == 0) {
            long long b = stack[top--];
            long long a = stack[top--];
            stack[++top] = a - b;
        } else if (strcmp(token, "*") == 0) {
            long long b = stack[top--];
            long long a = stack[top--];
            stack[++top] = a * b;
        } else if (strcmp(token, "/") == 0) {
            long long b = stack[top--];
            long long a = stack[top--];
            stack[++top] = a / b;
        } else {
            stack[++top] = atoll(token);
        }
        token = strtok(NULL, " ");
