long long largest_rectangle_area(const int *heights, int n) {
    int *stack = (int *)malloc((n + 1) * sizeof(int));
    int top = -1;
    long long max_area = 0;

    for (int i = 0; i <= n; i++) {
        int curr_h = (i == n) ? 0 : heights[i];
        while (top != -1 && curr_h < heights[stack[top]]) {
            int h = heights[stack[top--]];
            int width = (top == -1) ? i : (i - stack[top] - 1);
            long long area = (long long)h * width;
            if (area > max_area) {
                max_area = area;
            }
        }
        stack[++top] = i;
    }

    free(stack);
    return max_area;
}

