#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000

typedef struct {
    int data[MAX_SIZE];
    int top;
} Stack;

typedef struct {
    Stack in_stack;
    Stack out_stack;
} QueueTwoStacks;

void q_init(QueueTwoStacks *q) {
    q->in_stack.top = -1;
    q->out_stack.top = -1;
}

void transfer_if_needed(QueueTwoStacks *q) {
    if (q->out_stack.top == -1) {
        while (q->in_stack.top != -1) {
            q->out_stack.data[++q->out_stack.top] = q->in_stack.data[q->in_stack.top--];
        }
    }
}

void q_enqueue(QueueTwoStacks *q, int val) {
    q->in_stack.data[++q->in_stack.top] = val;
}

void q_dequeue(QueueTwoStacks *q) {
    transfer_if_needed(q);
    if (q->out_stack.top == -1) {
        printf("EMPTY\n");
        return;
    }
    printf("%d\n", q->out_stack.data[q->out_stack.top--]);
}

void q_front(QueueTwoStacks *q) {
    transfer_if_needed(q);
    if (q->out_stack.top == -1) {
        printf("EMPTY\n");
        return;
    }
    printf("%d\n", q->out_stack.data[q->out_stack.top]);
}

void q_is_empty(QueueTwoStacks *q) {
    int empty = (q->in_stack.top == -1 && q->out_stack.top == -1);
    printf("%s\n", empty ? "TRUE" : "FALSE");
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    QueueTwoStacks q;
    q_init(&q);

    char cmd[16];
    for (int i = 0; i < n; i++) {
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "ENQUEUE") == 0) {
            int val; scanf("%d", &val);
            q_enqueue(&q, val);
        } else if (strcmp(cmd, "DEQUEUE") == 0) {
            q_dequeue(&q);
        } else if (strcmp(cmd, "FRONT") == 0) {
            q_front(&q);
        } else if (strcmp(cmd, "ISEMPTY") == 0) {
            q_is_empty(&q);
        }
    }
    return 0;
}
